WITH recent_order_items AS (SELECT *, CAST(unit_price AS INT) AS unit_price_int FROM order_items WHERE unit_price < 220), summary AS (SELECT CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, MAX(unit_price) AS max_unit_price, SUM(quantity) AS total_quantity FROM recent_order_items GROUP BY CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, total_quantity FROM summary ORDER BY total_quantity DESC;
